"""
From findings to what gets entered: one entry per tender position, filled where the facts are complete and omitted
with a reason where they are not. Pure and model-free; the bid rules themselves live in `calc.py`.

This build prices a position as base price less the order discount. Surcharge, setup, packaging and bonus are not
applied yet.
"""
import re
from collections import defaultdict
from dataclasses import dataclass
from datetime import UTC, date, datetime, time, timedelta
from decimal import Decimal
from typing import Literal

from pydantic import BaseModel, Field

import calc
from evidence import Candidate, ErpFindings, Findings, MaterialFacts, Requirement, TenderFindings, TenderPosition
from parse import ParseError, parse_date, parse_datetime, parse_decimal, parse_int, parse_unit, split_address


class PlanEntry(BaseModel):
    position: str
    omit: bool = Field(description="True: leave the position out of the bid; `reason` says what was missing")
    reason: str = ""
    material_number: str = ""
    # the chosen material's attributes as the ERP writes them, to pick it in the bid form
    bore: str = ""
    stroke: str = ""
    pressure: str = ""
    mounting: str = ""
    certification: str = ""
    quantity: int | None = Field(default=None, description="Final quantity in pieces")
    lead_time_weeks: int | None = None
    unit_price: Decimal | None = Field(default=None, description="Final net unit price in EUR")
    base_unit_price: Decimal | None = None


class BidPlan(BaseModel):
    tender_reference: str
    decision: Literal["bid", "no_bid"] = "bid"
    discount_percent: Decimal = Decimal(0)
    total_net: Decimal = Decimal("0.00")
    entries: list[PlanEntry] = []
    notes: list[str] = Field(default_factory=list, description="Why something was omitted or assumed, for the trace")


class _Gap(calc.CalcError):
    """A fact this position needs was not established; the message is the omission reason."""


NUMERIC_KEYS = ("bore", "stroke", "pressure")  # compared as numbers; mounting and certification as text
_UNREADABLE = "\0unreadable: "  # marks an attribute value that could not be parsed, until the position needs it
_POSITION_WORD = r"(?:position|pos\.?|nr\.?|no\.?|#)"
_REVISION_WORD = r"(?:revision|rev\.?)"


def _ref(text: str, word: str = "") -> str:
    """An identifier for comparison: case and whitespace dropped, plus a leading label word such as "Pos."."""
    key = "".join(text.split()).casefold()
    if word:
        key = re.sub(rf"^{word}(?=.)", "", key)
    return key


def _position_ref(text: str) -> str:
    return re.sub(r"^0+(?=\d)", "", _ref(text, _POSITION_WORD).rstrip("."))


def _not_after(moment: datetime, scenario: datetime) -> bool:
    """Rule 21: dated no later than the scenario date. A scenario given as a bare day (midnight) covers that day."""
    if scenario.time() == time(0):
        return moment < scenario + timedelta(days=1)
    return moment <= scenario


def _labelled(label: str, parse, *args):
    """Run a parser and name the field in its error."""
    try:
        return parse(*args)
    except ParseError as e:
        raise ParseError(f"{label}: {e}") from e


def _short(error: Exception) -> str:
    return str(error).splitlines()[0]


def _attributes(shown: dict[str, str], number_format: str) -> dict[str, Decimal | str]:
    """Match attributes as values: numbers for bore, stroke and pressure, text otherwise."""
    out: dict[str, Decimal | str] = {}
    for name, value in shown.items():
        key = name.strip().casefold()
        if key in NUMERIC_KEYS:
            try:
                out[key] = parse_decimal(value, number_format)
            except ParseError as e:
                out[key] = _UNREADABLE + str(e)
        else:
            out[key] = value
    return out


def _unreadable(value: Decimal | str) -> bool:
    return isinstance(value, str) and value.startswith(_UNREADABLE)


# ---------------------------------------------------------------- tender Q&A


class _QA:
    """The Q&A records that apply on the scenario date, in the shape the calc helpers take."""

    def __init__(self, tender: TenderFindings, scenario: datetime, notes: list[str]):
        self.shown = tender.quantity_changes
        self.changes: list[calc.QuantityChange] = []  # `quantity` holds the index into `shown`, parsed when it wins
        self.withdrawn: set[str] = set()
        self.amendments: list[calc.Amendment] = []
        self.skipped = False  # a record could not be read, so "nothing else applies" is not certain

        for w in tender.withdrawals:
            if not w.date.strip():
                notes.append(f"withdrawal {w.answer} has no date: treated as in force")
                self.withdrawn.add(_ref(w.withdraws))
                continue
            when = self._when(w, f"withdrawal {w.answer}", notes)
            if when is not None and _not_after(when, scenario):
                self.withdrawn.add(_ref(w.withdraws))
        for index, c in enumerate(tender.quantity_changes):
            when = self._when(c, f"quantity change {c.answer}", notes)
            if when is not None and _not_after(when, scenario):
                self.changes.append(calc.QuantityChange(number=_ref(c.answer), date=when,
                                                        position=_position_ref(c.position), quantity=index))
        for a in tender.amendments:
            when = self._when(a, f"amendment {a.answer}", notes)
            if when is not None and _not_after(when, scenario):
                self.amendments.append(calc.Amendment(
                    date=when, revision=_ref(a.revision, _REVISION_WORD), requirement=_ref(a.requirement),
                    attributes=_attributes(a.attributes, a.number_format)))

    def _when(self, record, label: str, notes: list[str]) -> datetime | None:
        try:
            return parse_datetime(record.date, record.date_order, record.timezone)
        except ParseError as e:
            notes.append(f"{label} skipped: {e}")
            self.skipped = True
            return None


# ---------------------------------------------------------------- mail authority


class _Mail(calc.DatedRecord):
    index: int


def _governing(records: list, sender_local: str, reference: str, scenario: datetime, domain: str, label: str,
               notes: list[str]) -> int | None:
    """Rule 21: index of the latest record for the exact reference from sender_local@domain, not after the scenario."""
    dated = []
    for index, r in enumerate(records):
        try:
            local, sender_domain = split_address(r.sender)
            when = parse_datetime(r.date, r.date_order, r.timezone)
        except ParseError as e:
            if r.reference.strip() == reference.strip():
                notes.append(f"{label} mail skipped: {e}")
            continue
        if _not_after(when, scenario):
            dated.append(_Mail(reference=r.reference, sender=f"{local}@{sender_domain}", date=when, index=index))
    hit = calc.latest_authoritative(dated, reference, date.max, sender_local, domain)  # dates are filtered above
    return None if hit is None else hit.index


def _approval(findings: Findings, reference: str, scenario: datetime, domain: str,
              notes: list[str]) -> calc.Approval | None:
    """Rules 5 and 16: the governing director approval. An unreadable one counts as none, never an older one."""
    approving = [a for a in findings.mail.approvals if a.approves]
    index = _governing(approving, "leitung", reference, scenario, domain, "approval", notes)
    if index is None:
        notes.append("no discount approval applies: discount 0")
        return None
    shown = approving[index]
    try:
        percent = _labelled("approved percent", parse_decimal, shown.percent, shown.number_format)
        minimum = None
        if shown.min_order_value.strip():
            minimum = _labelled("minimum order value", parse_decimal, shown.min_order_value, shown.number_format)
        if not 0 <= percent <= 100:
            raise ParseError(f"approved percent {percent} out of range")
    except ParseError as e:
        notes.append(f"governing approval unreadable ({e}): discount 0")
        return None
    return calc.Approval(percent=percent, min_order_value=minimum)


@dataclass
class _Fx:
    rates: dict[str, Decimal]  # FX key or currency, upper-cased -> EUR per unit
    unreadable: dict[str, str]
    found: bool


def _fx(findings: Findings, reference: str, scenario: datetime, domain: str, notes: list[str]) -> _Fx:
    """Rule 22: the rates of the governing FX fixing (sent, exact reference, finance sender, not after the scenario)."""
    sent = [f for f in findings.mail.fx_fixings if f.sent]
    index = _governing(sent, "finanzen", reference, scenario, domain, "FX fixing", notes)
    fx = _Fx(rates={}, unreadable={}, found=index is not None)
    if index is not None:
        for key, value in sent[index].rates.items():
            try:
                fx.rates[key.strip().upper()] = parse_decimal(value, sent[index].number_format)
            except ParseError as e:
                fx.unreadable[key.strip().upper()] = str(e)
    return fx


@dataclass
class _Releases:
    reserves: dict[str, Decimal]  # reserve key, upper-cased -> reserve per end
    unreadable: dict[str, str]
    found: bool


def _releases(findings: Findings, reference: str, revision: str, scenario: datetime, domain: str,
              notes: list[str]) -> _Releases:
    """Rules 20 and 21: the reserves of the governing technical release for the current specification revision."""
    scoped = [r for r in findings.mail.technical_releases if revision and _ref(r.revision, _REVISION_WORD) == revision]
    index = _governing(scoped, "technik", reference, scenario, domain, "technical release", notes)
    out = _Releases(reserves={}, unreadable={}, found=index is not None)
    if index is not None:
        for key, value in scoped[index].reserves.items():
            try:
                out.reserves[key.strip().upper()] = parse_decimal(value, scoped[index].number_format)
            except ParseError as e:
                out.unreadable[key.strip().upper()] = str(e)
    return out


# ---------------------------------------------------------------- one position


@dataclass
class _State:
    tender: TenderPosition
    reason: str = ""  # first missing fact; empty = nothing missing so far
    pieces: int | None = None
    material: Candidate | None = None
    facts: MaterialFacts | None = None
    lead_time: int | None = None
    base: Decimal | None = None
    condition: calc.PriceCondition | None = None
    certain_no_match: bool = False

    def gap(self, error: Exception) -> None:
        self.reason = self.reason or _short(error)


def _pieces(tender: TenderPosition, requirement: Requirement | None, qa: _QA) -> int:
    """Rules 1, 13, 17: the tender quantity or the governing change, in pieces."""
    quantity = _labelled("tender quantity", parse_int, tender.quantity, tender.number_format)
    unit_text = tender.unit
    winner = calc.resolve_quantity(-1, _position_ref(tender.position), qa.changes, qa.withdrawn)
    if winner >= 0:
        change = qa.shown[winner]
        quantity = _labelled(f"quantity of change {change.answer}", parse_int, change.quantity, change.number_format)
        unit_text = change.unit if change.unit.strip() else unit_text
    unit = parse_unit(unit_text)
    per_set = None
    if unit is calc.Unit.SET and requirement is not None and requirement.pieces_per_set.strip():
        per_set = _labelled("pieces per set", parse_int, requirement.pieces_per_set, requirement.number_format)
    pieces = calc.to_pieces(quantity, unit, per_set)
    if pieces <= 0:
        raise _Gap(f"quantity is {pieces}")
    return pieces


def _reserve(requirement: Requirement, revision: str, releases: _Releases) -> Decimal:
    """Rule 20: the per-end reserve the governing technical release of this revision states for the requirement."""
    if not releases.found:
        raise _Gap("stroke is given as usable travel and no technical release for the revision applies")
    key = requirement.reserve_key.strip().upper()
    if key in releases.unreadable:
        raise ParseError(f"end reserve {key}: {releases.unreadable[key]}")
    if key not in releases.reserves:
        if not key and len(releases.reserves) == 1:
            return next(iter(releases.reserves.values()))
        raise _Gap(f"the technical release states no end reserve for key {key or '(none)'}")
    return releases.reserves[key]


def _requirement(requirement: Requirement, revision: str, qa: _QA, releases: _Releases) -> dict[str, Decimal | str]:
    """Rules 14 and 20: the requirement's match attributes after the amendments scoped to this revision and
    requirement, with a usable stroke turned into the nominal one."""
    key = _ref(requirement.requirement)
    if not revision and any(a.requirement == key for a in qa.amendments):
        raise _Gap("current specification revision unknown, so amendments cannot be scoped")
    shown = {k: getattr(requirement, k) for k in calc.MATCH_KEYS}
    attributes = calc.apply_amendments(_attributes(shown, requirement.number_format), qa.amendments, revision, key)
    for name in calc.MATCH_KEYS:
        value = attributes[name]
        if _unreadable(value):
            raise ParseError(f"requirement {name}: {str(value).removeprefix(_UNREADABLE)}")
    if requirement.usable_stroke:
        attributes["stroke"] = calc.nominal_stroke(attributes["stroke"], _reserve(requirement, revision, releases))
    return attributes


def _material(state: _State, required: dict[str, Decimal | str], erp: ErpFindings | None,
              notes: list[str]) -> Candidate:
    """Rule 3: the model's choice, cross-checked: among the candidates, active and equal on every match attribute."""
    if erp is None:
        raise _Gap("no ERP lookup for the requirement")
    if not erp.candidates:
        raise _Gap("no ERP candidates read for the requirement")
    listed = []
    for c in erp.candidates:
        attributes = _attributes({k: getattr(c, k) for k in calc.MATCH_KEYS}, c.number_format)
        listed.append({k: v for k, v in attributes.items() if not _unreadable(v)})  # unreadable never matches
    active = [(str(i), listed[i]) for i, c in enumerate(erp.candidates) if c.active is True]
    matches = [erp.candidates[int(i)] for i in calc.matching_materials(required, active)]
    chosen = _ref(erp.chosen)
    for c in matches:
        if _ref(c.material_number) == chosen:
            return c
    position = state.tender.position
    if len(matches) == 1:
        notes.append(f"position {position}: chosen material {erp.chosen or '(none)'} fails the cross-check; "
                     f"{matches[0].material_number} is the only active candidate that matches and is used")
        return matches[0]
    if matches:
        raise _Gap(f"several active candidates match and the chosen material {erp.chosen or '(none)'} is not one")

    # Wording is the model's call: two sources may name the same mounting or certification differently, so a chosen
    # active material that equals the requirement on every number is accepted on the model's reading of the text.
    numbers = tuple(k for k in calc.MATCH_KEYS if k in NUMERIC_KEYS)
    picked = next((c for c in erp.candidates if _ref(c.material_number) == chosen), None)
    if picked is not None and picked.active is True and calc.matching_materials(
            required, [("", listed[erp.candidates.index(picked)])], keys=numbers):
        notes.append(f"position {position}: chosen material {erp.chosen} equals the requirement on every number; "
                     "mounting or certification are worded differently and taken on the model's comparison")
        return picked

    # nothing matches: sure enough for no_bid only if the model chose none as well and every candidate is known
    # blocked or differs on a known number (a difference in wording alone is never certain)
    def differs(attributes: dict[str, Decimal | str]) -> bool:
        return any(k in attributes and attributes[k] != "" and required[k] != ""
                   and not calc.matching_materials(required, [("", attributes)], keys=(k,)) for k in numbers)

    state.certain_no_match = (not chosen and erp.all_candidates_read
                              and all(required[k] != "" for k in calc.MATCH_KEYS)
                              and all(c.active is False or differs(listed[i]) for i, c in enumerate(erp.candidates)))
    if not chosen:
        raise _Gap("no material chosen and no active candidate matches the requirement")
    if picked is None:
        raise _Gap(f"chosen material {erp.chosen} is not among the candidates")
    if picked.active is not True:
        raise _Gap(f"chosen material {erp.chosen} is not active" if picked.active is False
                   else f"status of chosen material {erp.chosen} unknown")
    raise _Gap(f"chosen material {erp.chosen} does not match the requirement exactly")


def _weeks(label: str, text: str, number_format: str) -> int:
    """A lead time in weeks; one stated in days counts only if it is whole weeks."""
    value = _labelled(label, parse_int, text, number_format)
    if re.search(r"\b(tage?n?|days?)\b", text, re.IGNORECASE):
        if value % 7:
            raise ParseError(f"{label}: {text.strip()!r} is not whole weeks")
        return value // 7
    return value


def _lead_time(facts: MaterialFacts, pooled: int, open_demand: bool) -> int:
    """Rules 6 and 15: stock lead time if free stock covers the material's pooled demand, else production."""
    stock = _labelled("free stock", parse_int, facts.free_stock, facts.number_format)
    # ask calc which of the two lead times applies (0 = stock, 1 = production), then read only that one
    probe = calc.Material(material_number=facts.material_number, free_stock=stock, stock_lead_time_weeks=0,
                          production_lead_time_weeks=1)
    from_stock = calc.lead_time(calc.PositionInput(position="", quantity=0, material=probe), pooled) == 0
    if from_stock and open_demand:
        raise _Gap("pooled demand unknown: another position with this material has no quantity")
    if from_stock:
        return _weeks("stock lead time", facts.stock_lead_time_weeks, facts.number_format)
    return _weeks("production lead time", facts.production_lead_time_weeks, facts.number_format)


def _condition(facts: MaterialFacts, day: date, fx: _Fx, position: str, notes: list[str]) -> calc.PriceCondition:
    """Rule 4: the price condition valid on the scenario day, parsed. Other conditions only need readable dates."""
    dated = []
    for c in facts.conditions:
        start = _labelled("price validity start", parse_date, c.valid_from, c.date_order)
        open_end = not re.search(r"\d", c.valid_to)  # blank or a word such as "open": no end
        end = None if open_end else _labelled("price validity end", parse_date, c.valid_to, c.date_order)
        dated.append(calc.PriceCondition(valid_from=start, valid_to=end, scales=[]))
    valid = calc.valid_condition(dated, day)
    shown = next(c for c, d in zip(facts.conditions, dated) if d is valid)
    number_format = shown.number_format or facts.number_format

    scales = []
    for s in shown.scales:
        lone_price = len(shown.scales) == 1 and not s.min_quantity.strip()  # one price without a scale table
        minimum = 0 if lone_price else _labelled("scale quantity", parse_int, s.min_quantity, number_format)
        scales.append(calc.PriceScale(min_quantity=minimum, price=_labelled("price", parse_decimal, s.price,
                                                                            number_format)))
    currency = shown.currency.strip().upper().replace("€", "EUR")
    if not currency and any("€" in s.price or "EUR" in s.price.upper() for s in shown.scales):
        currency = "EUR"
    if not currency:
        raise _Gap("currency of the price condition unknown")
    if shown.price_unit.strip():
        price_unit = _labelled("price unit", parse_int, shown.price_unit, number_format)
    else:
        price_unit = 1
        notes.append(f"position {position}: no price unit stated, assumed 1 piece")
    fx_key = shown.fx_key.strip().upper() or None
    if currency != "EUR":
        key = fx_key or currency
        if key in fx.unreadable:
            raise ParseError(f"FX rate {key}: {fx.unreadable[key]}")
        if key not in fx.rates and currency not in fx.rates:
            raise _Gap(f"no usable FX fixing for {key}" if not fx.found else f"the FX fixing has no rate for {key}")
    return calc.PriceCondition(valid_from=valid.valid_from, valid_to=valid.valid_to, currency=currency, fx_key=fx_key,
                               price_unit=price_unit, scales=scales)


def _bid_input(states: list[_State], reference: str, day: date, fx: _Fx,
               approval: calc.Approval | None = None) -> calc.BidInput:
    """Priced positions as calc input. Lead times are decided here (pooled over all positions), so calc gets them
    fixed; the stock is left at 0 and both lead times set to the decided one."""
    positions = []
    for s in states:
        assert s.material is not None and s.pieces is not None and s.condition is not None
        weeks = s.lead_time or 0
        material = calc.Material(material_number=s.material.material_number, stock_lead_time_weeks=weeks,
                                 production_lead_time_weeks=weeks)
        positions.append(calc.PositionInput(position=s.tender.position, quantity=s.pieces, material=material,
                                            conditions=[s.condition]))
    return calc.BidInput(tender_reference=reference, scenario_date=day, positions=positions, approval=approval,
                         fx_rates=fx.rates)


# ---------------------------------------------------------------- the plan


def build_plan(findings: Findings, tender_reference: str, scenario_date: datetime, bidder_domain: str) -> BidPlan:
    """The bid the findings support. `scenario_date` is timezone-aware; `bidder_domain` is the bidder mailbox's
    domain, which authorises senders."""
    notes: list[str] = []
    scenario = scenario_date if scenario_date.tzinfo else scenario_date.replace(tzinfo=UTC)
    day = scenario.date()  # the scenario's own calendar day, for validity windows written as plain dates
    domain = bidder_domain.strip().lstrip("@").lower()

    states: list[_State] = []
    seen: set[str] = set()
    for tender in findings.tender.positions:
        key = _position_ref(tender.position)
        if key in seen:
            notes.append(f"position {tender.position} listed twice: first entry kept")
            continue
        seen.add(key)
        states.append(_State(tender=tender))
    if not states:
        notes.append("no tender positions found")

    qa = _QA(findings.tender, scenario, notes)
    approval = _approval(findings, tender_reference, scenario, domain, notes)
    fx = _fx(findings, tender_reference, scenario, domain, notes)
    requirements = {_ref(r.requirement): r for r in findings.spec.requirements}
    lookups = {_ref(key): e for key, e in findings.erp.items()} | {
        _ref(e.requirement): e for e in findings.erp.values() if e.requirement.strip()}
    revision = _ref(findings.spec.current_revision, _REVISION_WORD)
    releases = _releases(findings, tender_reference, revision, scenario, domain, notes)

    # quantity and material are established independently, so one missing fact does not hide the other
    for s in states:
        requirement = requirements.get(_ref(s.tender.requirement)) if s.tender.requirement.strip() else None
        try:
            s.pieces = _pieces(s.tender, requirement, qa)
        except ValueError as e:
            s.gap(e)
        try:
            if requirement is None:
                raise _Gap(f"requirement {s.tender.requirement or '(none)'} not found in the specification")
            required = _requirement(requirement, revision, qa, releases)
            erp = lookups.get(_ref(requirement.requirement))
            s.material = _material(s, required, erp, notes)
            facts = erp.facts if erp is not None else None
            if facts is None or _ref(facts.material_number) != _ref(s.material.material_number):
                raise _Gap(f"no stock and price facts for material {s.material.material_number}")
            s.facts = facts
        except ValueError as e:
            s.gap(e)

    # rules 3 and 8: no_bid only when it is certain that a position has no matching active material
    sure = findings.tender.complete and findings.spec.complete and bool(revision) and not qa.skipped
    unmatched = [s for s in states if s.certain_no_match]
    if unmatched and sure:
        numbers = ", ".join(s.tender.position for s in unmatched)
        notes.append(f"no_bid: position {numbers} has no exactly matching active material; tender and specification "
                     "were read completely and every ERP candidate was checked")
        entries = [PlanEntry(position=s.tender.position, omit=True,
                             reason=s.reason if s.certain_no_match else "no_bid") for s in states]
        return BidPlan(tender_reference=tender_reference, decision="no_bid", entries=entries, notes=notes,
                       discount_percent=calc.effective_discount(approval, None))
    for s in unmatched:
        notes.append(f"position {s.tender.position}: no matching active material, but the findings are not complete "
                     "enough for no_bid; position omitted instead")

    # rule 15: demand is pooled per material over every position that selects it, priced or not
    pooled: dict[str, int] = defaultdict(int)
    open_demand: set[str] = set()
    for s in states:
        if s.material is not None:
            key = _ref(s.material.material_number)
            pooled[key] += s.pieces or 0
            if s.pieces is None:
                open_demand.add(key)

    for s in states:
        if s.material is None or s.facts is None or s.pieces is None:
            continue
        key = _ref(s.material.material_number)
        try:
            s.lead_time = _lead_time(s.facts, pooled[key], key in open_demand)
        except ValueError as e:
            s.gap(e)
        try:  # rule 22, through calc: valid condition, this position's scale, price unit, FX, HALF_UP to cents
            s.condition = _condition(s.facts, day, fx, s.tender.position, notes)
            alone = calc.calculate(_bid_input([s], tender_reference, day, fx))
            s.base = alone.positions[0].base_unit_price
        except ValueError as e:
            s.condition = None
            s.gap(e)

    # rule 16: the threshold looks at all tender positions; with a price missing only the known part can prove it
    priced = [s for s in states if s.base is not None and s.pieces is not None]
    order_value = calc.money(sum((s.pieces * s.base for s in priced), Decimal(0)))  # type: ignore[operator]
    discount = calc.effective_discount(approval, order_value)
    if approval is not None and approval.min_order_value is not None:
        if discount:
            notes.append(f"order value {order_value} reaches the approval's minimum {approval.min_order_value}")
        elif len(priced) < len(states):
            notes.append(f"known order value {order_value} is below the approval's minimum "
                         f"{approval.min_order_value} and some base prices are unknown: discount 0")
        else:
            notes.append(f"order value {order_value} is below the approval's minimum {approval.min_order_value}: "
                         "discount 0")

    filled = [s for s in states if not s.reason]
    total = Decimal("0.00")
    prices: dict[str, Decimal] = {}
    if filled:
        try:  # unit price = base x (1 - discount), rounded once; total = sum of quantity x rounded unit price
            decided = calc.Approval(percent=discount) if discount else None
            result = calc.calculate(_bid_input(filled, tender_reference, day, fx, decided))
            prices = {p.position: p.unit_price for p in result.positions}
            total = result.total_net
        except ValueError as e:  # not expected: every input was priced alone above
            for s in filled:
                s.gap(e)
        notes.append("surcharge, setup, packaging and bonus are not applied yet: unit price is base price less "
                     "discount")

    entries = []
    for s in states:
        if s.reason or s.material is None:
            notes.append(f"position {s.tender.position} omitted: {s.reason}")
            entries.append(PlanEntry(position=s.tender.position, omit=True, reason=s.reason))
            continue
        m = s.material
        entries.append(PlanEntry(
            position=s.tender.position, omit=False, material_number=m.material_number, bore=m.bore, stroke=m.stroke,
            pressure=m.pressure, mounting=m.mounting, certification=m.certification, quantity=s.pieces,
            lead_time_weeks=s.lead_time, unit_price=prices[s.tender.position], base_unit_price=s.base))
    return BidPlan(tender_reference=tender_reference, decision="bid", discount_percent=discount, total_net=total,
                   entries=entries, notes=notes)

"""
One website in one tab, and the actions a model may take on it.

`SiteSession` owns the tab (and popups it opens) for one website. After every action it settles the page with
generic helpers that make no decisions: sign in with the run's credentials when a login form shows, accept only
the necessary cookies, pass "slide to unlock / not a robot" checks, close modal popups through their close button,
reload transient error pages and sign in again after a session timeout. What to open, search, read and enter is
left to the model through `TOOLS`.
"""
import asyncio
import re
import time
from dataclasses import dataclass, field
from urllib.parse import urljoin, urlparse

from extract import locate, observe
from playwright.async_api import BrowserContext, Dialog, Page
from pydantic_ai import RunContext
from tracing import Trace

MAX_VIEW = 14000  # characters of a page shown at once; read_more pages through the rest
ACTION_MS = 8000  # default limit of one browser operation (reading a label, typing, a scripted click)
HELPER_SECONDS = 20  # a helper or a page reading that takes longer hangs on a stuck page and is given up
MAX_PAGES = 15  # pages read_all_pages follows in one call
MAX_READ = 8  # pages read_pages opens in one call
MAX_PAGED = 45000  # characters read_all_pages or read_pages return in one call

# Closes modal <dialog>s and aria-modal popups through their own close button as soon as they open, and records
# what it closed. Links inside popups ("accept and continue") are never followed.
AUTO_CLOSE_JS = r"""
(() => {
  if (window.__arInit) return;
  window.__arInit = true;
  const CLOSE = /^(×|✕|✖|x|schließen|schliessen|close|dismiss|ausblenden|später|later|nicht jetzt|not now)$/i;
  const closed = (window.__arClosed = window.__arClosed || []);
  function closeButton(d) {
    for (const b of d.querySelectorAll('button,[role=button]')) {
      const name = (b.getAttribute('aria-label') || b.textContent || '').trim();
      if (CLOSE.test(name) || b.hasAttribute('data-close')) return b;
    }
    return null;
  }
  function check() {
    for (const d of document.querySelectorAll('dialog[open],[role=dialog][aria-modal=true],[role=alertdialog]')) {
      const modal = d.tagName !== 'DIALOG' || d.matches(':modal');
      if (!modal || d.dataset.arClosed) continue;
      const b = closeButton(d);
      if (!b) continue;
      d.dataset.arClosed = '1';
      closed.push((d.getAttribute('aria-label') || d.querySelector('h1,h2,h3')?.textContent || 'popup').trim());
      b.click();
      if (d.tagName === 'DIALOG' && d.open) d.close();
    }
  }
  const start = () => {
    check();
    new MutationObserver(check).observe(document.documentElement,
      {subtree: true, childList: true, attributes: true, attributeFilter: ['open', 'aria-modal', 'style', 'class']});
  };
  if (document.documentElement) start(); else document.addEventListener('DOMContentLoaded', start);
})();
"""

# "Slide to unlock" plus "I am not a robot" checks in any frame: drag the slider to its end, tick only boxes that
# are labelled as a robot check. Other checkboxes (terms, declarations) are left to the model.
HUMAN_CHECK_JS = r"""
() => {
  const ROBOT = /roboter|robot|mensch\b|human/i, SLIDE = /entsperr|unlock|zieh|slide|schieb/i;
  const labels = e => e.labels ? Array.from(e.labels).map(l => l.textContent) : [];
  const text = e => [e.getAttribute('aria-label') || '', ...labels(e)].join(' ');
  const done = [];
  for (const r of document.querySelectorAll('input[type=range]')) {
    const around = text(r) + ' ' + (r.parentElement ? r.parentElement.textContent : '');
    const max = r.max || '100';
    if (!SLIDE.test(around) || r.value === max || r.disabled) continue;
    r.value = max;
    r.dispatchEvent(new Event('input', {bubbles: true}));
    r.dispatchEvent(new Event('change', {bubbles: true}));
    done.push('unlock slider');
  }
  for (const c of document.querySelectorAll('input[type=checkbox]')) {
    if (c.checked || c.disabled || !ROBOT.test(text(c))) continue;
    c.click();
    done.push('robot check');
  }
  return done;
}
"""

ERROR_PAGE = re.compile(r"vorübergehend nicht verfügbar|temporarily unavailable|service unavailable|bad gateway|"
                        r"gateway time-?out|internal server error|bitte versuchen sie es (später )?erneut",
                        re.IGNORECASE)
COOKIE = re.compile(r"cookie", re.IGNORECASE)
COOKIE_ANSWER = re.compile(r"akzeptier|accept|zustimm|agree|ablehn|reject|erlaub|allow|bestätig|confirm|ok\b",
                           re.IGNORECASE)
COOKIE_MINIMAL = re.compile(r"notwendig|erforderlich|necessary|essential|nur technisch|ablehnen|reject|decline",
                            re.IGNORECASE)


@dataclass
class SiteSession:
    """A website of the run (`siteId`, `url`, `credentials`) worked in its own tab."""

    site: dict
    context: BrowserContext
    trace: Trace
    pages: list[Page] = field(default_factory=list)
    events: list[str] = field(default_factory=list)  # what the helpers did since the model last looked
    view: str = ""
    lock: asyncio.Lock = field(default_factory=asyncio.Lock)
    stamp: int = 0
    logins: int = 0
    seen: str = ""  # every view's text this session, to check notes against
    label: str = ""  # names this tab in the trace when a website is worked in several tabs
    runs: list[dict] = field(default_factory=list)  # per worker goal: requests, seconds, outcome

    @property
    def name(self) -> str:
        return self.label or self.site["siteId"]

    async def close(self) -> None:
        """Close this session's tab and the windows it opened; the website's sign-in stays with the context."""
        for page in self.pages:
            try:
                await page.close()
            except Exception:
                pass
        self.pages = []

    @property
    def page(self) -> Page:
        open_pages = [p for p in self.pages if not p.is_closed()]
        self.pages = open_pages
        return open_pages[-1]

    async def start(self) -> str:
        """Open the site's start page in a new tab, signed in."""
        await self.context.add_init_script(AUTO_CLOSE_JS)
        page = await self.context.new_page()
        self._watch(page)
        await self._goto(self.site["url"])
        return await self.look()

    def _watch(self, page: Page) -> None:
        self.pages.append(page)
        page.set_default_timeout(ACTION_MS)  # an operation on a stuck page fails soon instead of hanging
        page.on("dialog", self._on_dialog)
        page.on("popup", self._on_popup)

    def _on_popup(self, popup: Page) -> None:
        self._watch(popup)
        self.events.append(f"a new window opened ({popup.url}); you are now in it, it closes back to the last one")

    async def _on_dialog(self, dialog: Dialog) -> None:
        self.events.append(f"browser {dialog.type} said: {dialog.message!r}; accepted")
        await dialog.accept()

    async def _goto(self, url: str) -> None:
        try:
            await self.page.goto(url, wait_until="domcontentloaded", timeout=30000)
        except Exception as error:  # a slow load event still leaves a usable page
            self.events.append(f"navigation was slow or failed: {str(error).splitlines()[0][:160]}")
        await self.settle()

    async def settle(self) -> None:
        """Let the page finish, then run the generic helpers until nothing changes."""
        page = self.page
        self.logins = 0  # a timeout later in the run may need a fresh sign-in
        unlocked = False
        for _ in range(6):
            try:
                await page.wait_for_load_state("domcontentloaded", timeout=15000)
                await page.wait_for_load_state("networkidle", timeout=2500)
                for frame in page.frames[1:]:  # an embedded document may still be loading its next page
                    await frame.wait_for_load_state("domcontentloaded", timeout=3000)
            except Exception:
                pass
            if (await self._safely(self._login, page) or await self._safely(self._cookies, page)
                    or await self._safely(self._error_page, page)):
                page = self.page
                continue
            if await self._safely(self._human_check, page):
                unlocked = True
                continue
            break
        if unlocked:
            await self.finish_loading()
        await self._collect_closed(page)

    async def finish_loading(self, rounds: int = 4, pause: float = 0.5) -> None:
        """Let a page that fills in step by step finish (a pane that loads once a check is passed, a text that loads
        once the pane is there, a further check inside it): pause until two readings in a row are the same."""
        before = None
        for _ in range(rounds):
            await asyncio.sleep(pause)
            page = self.page
            try:
                await page.wait_for_load_state("networkidle", timeout=2500)
            except Exception:
                pass
            await self._safely(self._human_check, page)
            try:
                now = _plain(await asyncio.wait_for(observe(page, "settle"), HELPER_SECONDS))
            except Exception:
                return
            if now == before:
                return
            before = now

    async def _safely(self, helper, page: Page) -> bool:
        """A helper that fails (a slow page, a detached element) just did nothing; the model sees the page as is."""
        try:
            return await asyncio.wait_for(helper(page), HELPER_SECONDS)
        except Exception as error:
            reason = (str(error).splitlines() or [type(error).__name__])[0][:160]
            self.trace.event(self.name, "helper_error", helper=helper.__name__, error=reason)
            return False

    async def _login(self, page: Page) -> bool:
        password = page.locator("input[type=password]:visible")
        if not await password.count() or self.logins >= 2:
            return False
        self.logins += 1
        form = password.first.locator("xpath=ancestor::form[1]")
        scope = form if await form.count() else page.locator("body")
        user = scope.locator("input:visible:not([type=password]):not([type=hidden]):not([type=checkbox])"
                             ":not([type=radio]):not([type=submit]):not([type=button])")
        if not await user.count():
            return False
        creds = self.site["credentials"]
        await user.first.fill(creds["username"])
        await password.first.fill(creds["password"])
        try:
            await password.first.press("Enter", timeout=5000)
        except Exception:
            pass  # the form was sent; the page is still loading, which settle waits for
        self.events.append("signed in with this run's login")
        self.trace.event(self.name, "helper", action="login", url=page.url)
        await asyncio.sleep(0.3)
        return True

    async def _cookies(self, page: Page) -> bool:
        buttons = page.locator("button:visible, input[type=submit]:visible")
        candidates = []
        for i in range(min(await buttons.count(), 20)):
            button = buttons.nth(i)
            text = (await button.inner_text() if await button.evaluate("e => e.tagName") == "BUTTON"
                    else await button.get_attribute("value")) or ""
            if COOKIE.search(text) and COOKIE_ANSWER.search(text):
                candidates.append((not COOKIE_MINIMAL.search(text), text.strip(), button))
        if not candidates:
            return False
        candidates.sort(key=lambda c: c[0])  # the necessary-only choice first
        _, text, button = candidates[0]
        await button.click()
        self.events.append(f"cookie notice answered with {text!r}")
        self.trace.event(self.name, "helper", action="cookies", choice=text)
        await asyncio.sleep(0.3)
        return True

    async def _human_check(self, page: Page) -> bool:
        done = []
        for frame in page.frames:
            try:
                done += await frame.evaluate(HUMAN_CHECK_JS)
            except Exception:
                continue
        if not done:
            return False
        self.events.append("unlocked a human check (" + ", ".join(sorted(set(done))) + ")")
        self.trace.event(self.name, "helper", action="human_check", done=done)
        await asyncio.sleep(0.4)
        return True

    async def _error_page(self, page: Page) -> bool:
        try:
            body = await page.locator("body").inner_text(timeout=3000)
        except Exception:
            return False
        if len(body) > 1500 or not ERROR_PAGE.search(body):
            return False
        self.events.append("a transient error page showed; reloaded")
        self.trace.event(self.name, "helper", action="reload", url=page.url)
        await asyncio.sleep(1.0)
        try:
            await page.reload(wait_until="domcontentloaded", timeout=30000)
        except Exception:
            pass
        return True

    async def _collect_closed(self, page: Page) -> None:
        for frame in page.frames:
            try:
                closed = await asyncio.wait_for(frame.evaluate("(window.__arClosed || []).splice(0)"), 5)
            except Exception:
                continue
            for title in closed:
                self.events.append(f"closed popup {title!r} with its close button")
                self.trace.event(self.name, "helper", action="close_popup", title=title)

    async def look(self, offset: int = 0) -> str:
        """What the model sees: the helpers' events, the tab, then the page text with refs."""
        page = self.page
        await self._collect_closed(page)
        self.stamp += 1
        if offset == 0:
            try:
                self.view = await asyncio.wait_for(observe(page, str(self.stamp)), HELPER_SECONDS)
            except Exception as error:
                await asyncio.sleep(1.0)
                try:
                    self.view = await asyncio.wait_for(observe(page, str(self.stamp)), HELPER_SECONDS)
                except Exception:
                    self.view = f"(the page could not be read: {type(error).__name__}; reload it or go back)"
        try:
            title = await asyncio.wait_for(page.title(), 5)
        except Exception:
            title = ""
        header = [f"URL: {page.url}", f"Title: {title}"]
        if len(self.pages) > 1:
            header.append(f"Windows open: {len(self.pages)} (you are in the newest)")
        if self.events:
            header.append("Since your last action: " + "; ".join(self.events))
            self.events.clear()
        if offset == 0:
            self.trace.event(self.name, "view", quiet=True, url=page.url, text=self.view)
            self.seen += "\n" + self.view
        text = self.view[offset:offset + MAX_VIEW]
        rest = len(self.view) - offset - len(text)
        if rest > 0:
            text += f"\n[... {rest} more characters: read_more(offset={offset + len(text)})]"
        return "\n".join(header) + "\n\n" + text

    async def act(self, kind: str, ref: str, fn, typed: str = "") -> str:
        """Run one action on the element `ref`, settle, and return the new view. `typed` goes into the trace."""
        async with self.lock:
            element = await locate(self.page, ref)
            if element is None:
                return f"No element {ref} on this page (refs change with every view).\n\n" + await self.look()
            started = time.monotonic()
            before = (self.page.url, self.view)
            try:
                await fn(element)
            except Exception as error:
                first = str(error).splitlines()[0][:200]
                self.trace.event(self.name, "action_error", action=kind, ref=ref, error=first)
                return f"{kind} {ref} failed: {first}\n\n" + await self.look()
            await asyncio.sleep(0.25)
            await self.settle()
            if kind == "click" and time.monotonic() - started < 0.5:
                # nothing was loading yet: a click that loads (an embedded document's next page) may start late
                await asyncio.sleep(0.4)
                await self.settle()
            self.trace.event(self.name, "action", action=kind, ref=ref, seconds=round(time.monotonic() - started, 2),
                             **({"typed": typed[:80]} if typed else {}))
            view = await self.look()
            if (self.page.url, self.view) == before:
                view = (f"Nothing on the page changed after {kind} {ref}. Do not repeat it; check the page for what "
                        f"is still missing (a required field, a checkbox, another button).\n\n") + view
            return view


async def _click(element) -> None:
    try:
        await element.click(timeout=5000)
    except Exception:  # covered by a banner or outside the scroll box
        await asyncio.wait_for(element.evaluate("e => e.click()"), 5)


@dataclass
class Deps:
    """What a worker's tools reach: its website and the notes it keeps for the orchestrator."""

    session: SiteSession
    notes: dict[str, str] = field(default_factory=dict)
    refused: dict[str, int] = field(default_factory=dict)
    deadline: float | None = None  # time.monotonic() value the worker has to be done by


async def goto(ctx: RunContext[Deps], url: str) -> str:
    """Open a URL or a path on this website (e.g. a link's target from the page)."""
    session = ctx.deps.session
    target = urljoin(session.page.url, url)
    if urlparse(target).netloc != urlparse(session.site["url"]).netloc:
        return f"{target} is not on this website ({session.site['url']}); stay on it."
    async with session.lock:
        await session._goto(target)
        session.trace.event(session.name, "action", action="goto", url=target)
        return await session.look()


async def click(ctx: RunContext[Deps], ref: str) -> str:
    """Click the element with this ref (link, button, tab, summary, checkbox)."""
    return await ctx.deps.session.act("click", ref, _click)


async def fill(ctx: RunContext[Deps], ref: str, text: str, submit: bool = False) -> str:
    """Type text into a textbox or textarea (replaces its content), or set a slider to a number.

    submit=true presses Enter afterwards, which runs a search or sends the field's form.
    """
    async def run(element):
        if await element.evaluate("e => e.type") == "range":
            await element.evaluate("(e, v) => { e.value = v; e.dispatchEvent(new Event('input', {bubbles: true}));"
                                   " e.dispatchEvent(new Event('change', {bubbles: true})); }", text)
        else:
            await element.fill(text, timeout=5000)
        if submit:
            await element.press("Enter")
    return await ctx.deps.session.act("fill", ref, run, typed=text)


async def select(ctx: RunContext[Deps], ref: str, option: str) -> str:
    """Choose an option of a select by its visible text."""
    async def run(element):
        try:
            await element.select_option(label=option, timeout=5000)
        except Exception:
            await element.select_option(option, timeout=5000)
    return await ctx.deps.session.act("select", ref, run)


async def check(ctx: RunContext[Deps], ref: str, checked: bool = True) -> str:
    """Tick (checked=true) or untick a checkbox or radio button."""
    async def run(element):
        try:
            await element.set_checked(checked, timeout=5000)
        except Exception:
            await element.evaluate("(e, c) => { if (e.checked !== c) e.click(); }", checked)
    return await ctx.deps.session.act("check", ref, run)


async def back(ctx: RunContext[Deps], url: str = "", ref: str = "") -> str:
    """Go back to the previous page. It takes no arguments; with a url it opens that page instead."""
    if url:
        return await goto(ctx, url)
    session = ctx.deps.session
    async with session.lock:
        try:
            await session.page.go_back(wait_until="domcontentloaded", timeout=15000)
        except Exception:
            pass
        await session.settle()
        return await session.look()


async def read_more(ctx: RunContext[Deps], offset: int) -> str:
    """Show the rest of a long page from the offset the view gave."""
    return await ctx.deps.session.look(offset)


CONTROL = re.compile(r'\[(e\d+) ([\w-]+) "([^"\n]*)"((?: -> [^\]\n]*)?(?: expanded=\w+)?)( disabled)?\]')
REF = re.compile(r"\[e\d+ ")
FRAME_OPEN, FRAME_CLOSE = "[frame ", "[/frame]"


def _plain(text: str) -> str:
    """A view without its refs, which change with every view: for comparing pages and for pages no longer open."""
    return REF.sub("[", text)


def _content(text: str) -> str:
    """What a page says, without refs, link targets and frame addresses (those count pages up while the content
    repeats): two pages with the same content are the same page."""
    lines = [line for line in _plain(text).splitlines() if not line.startswith(FRAME_OPEN)]
    return re.sub(r'" -> [^\]\n]*\]', '"]', "\n".join(lines))


def _controls(view: str, kind: str, name: str) -> list[re.Match]:
    return [m for m in CONTROL.finditer(view) if m.group(2) == kind and m.group(3) == name]


def _paged_part(view: str, at: int) -> tuple[str, bool]:
    """The part of `view` a paging control at offset `at` belongs to: the innermost embedded document around it
    (and True), or the whole view when the control is on the page itself."""
    open_at: list[int] = []
    position = 0
    for line in view.splitlines(keepends=True):
        stripped = line.strip()
        if position > at and not open_at:
            break
        if stripped.startswith(FRAME_OPEN) and not stripped.endswith("(separate)]"):
            open_at.append(position)
        elif stripped == FRAME_CLOSE and open_at:
            start = open_at.pop()
            if start <= at < position:
                return view[start:position + len(line)].strip(), True
        position += len(line)
    return view, False


def _new_lines(part: str, previous: str, framed: bool) -> tuple[str, int]:
    """`part` without the leading lines it shares with the previous page, and how many were dropped. An embedded
    document is cut only when it grew (a "load more" list); a whole page always loses its repeated top."""
    lines, old = part.splitlines(), _plain(previous).splitlines()
    same = 0
    while same < len(lines) and same < len(old) and _plain(lines[same]) == old[same]:
        same += 1
    if framed and same < max(3, len(old) - 3):  # a new page of the document, not the old one with more rows
        return part, 0
    return "\n".join(lines[same:]), same


async def read_all_pages(ctx: RunContext[Deps], ref: str) -> str:
    """Read every further page of the list, table or document you are looking at, in one step.

    Pass the ref of the control that leads to its next page ("next", "more", ">", a page number). It is followed
    again and again and all pages come back as one text. Use it instead of clicking through pages one by one.
    """
    session, deadline = ctx.deps.session, ctx.deps.deadline
    view = session.view
    first = next((m for m in CONTROL.finditer(view) if m.group(1) == ref.strip()), None)
    if first is None:
        return f"No link or button {ref} on this page (refs change with every view).\n\n" + await session.look()
    kind, name = first.group(2), first.group(3)
    same = _controls(view, kind, name)
    ordinal = next(i for i, m in enumerate(same) if m.group(1) == first.group(1))
    part, framed = _paged_part(view, first.start())
    pages, plain, control, reason = [part], [_content(part)], first, ""
    open_page = 0  # index of the page the browser shows when the loop ends
    used = min(len(part), MAX_VIEW)
    while True:
        if control is None:
            reason = f"the page shows no {kind} {name!r} any more: this was the last page"
        elif control.group(5):
            reason = f"the {kind} {name!r} is disabled: this was the last page"
        elif len(pages) >= MAX_PAGES:
            reason = f"{MAX_PAGES} pages are read per call; call read_all_pages again to continue from here"
        elif used >= MAX_PAGED:
            reason = "the output limit is reached; call read_all_pages again to continue from here"
        elif deadline is not None and time.monotonic() > deadline - 5:
            reason = "time is running out"
        if reason:
            break
        before = (session.page.url, _plain(session.view))
        await session.act("click", control.group(1), _click)
        if (session.page.url, _plain(session.view)) == before:  # a slow page: give it a moment before concluding
            await asyncio.sleep(1.5)
            async with session.lock:
                await session.settle()
                await session.look()
        view = session.view
        if name.isdigit():  # numbered page links: the next number leads on
            name = str(int(name) + 1)
        same = _controls(view, kind, name)
        control = same[min(ordinal, len(same) - 1)] if same else None
        if not framed:
            part = view
        elif control:
            part = _paged_part(view, control.start())[0]
        else:  # the control went with the last page: take the embedded document that changed
            blocks = [_paged_part(view, m.start() + 1)[0] for m in re.finditer(re.escape(FRAME_OPEN), view)]
            fresh = [block for block in blocks if _content(block) not in plain]
            part = min(fresh, key=len) if fresh else pages[open_page]
        if (session.page.url, _plain(view)) == before:
            reason = f"following {first.group(3)!r} changed nothing: this was the last page"
        elif _content(part) in plain:
            open_page = plain.index(_content(part))
            reason = f"the content of page {open_page + 1} came again: there are no further pages"
        if reason:
            if _content(part) == plain[open_page]:
                pages[open_page] = part  # the same content with the refs that work now
            break
        pages.append(part)
        plain.append(_content(part))
        open_page = len(pages) - 1
        used += min(len(part), MAX_VIEW)
    out = [f"URL: {session.page.url}", f"Read {len(pages)} page(s) by following {kind} {first.group(3)!r}; stopped "
           f"because {reason}.", "Only the paged part is shown, and only the refs of the page marked open work; "
           "read_more(offset=0) shows the whole current page."]
    if session.events:
        out.append("Since your last action: " + "; ".join(session.events))
        session.events.clear()
    for number, page_text in enumerate(pages, 1):
        cut_note = ""
        if number > 1:
            page_text, dropped = _new_lines(page_text, pages[number - 2], framed)
            if dropped:
                cut_note = f" ({dropped} leading lines are the same as on the page before and not repeated)"
        if number - 1 != open_page:
            page_text = _plain(page_text)
        if len(page_text) > MAX_VIEW:
            cut = len(page_text) - MAX_VIEW
            page_text = page_text[:MAX_VIEW] + f"\n[... page {number} is cut here, {cut} more characters]"
        out.append(f"\n===== page {number}{' (open now)' if number - 1 == open_page else ''}{cut_note} =====\n"
                   f"{page_text}")
    session.trace.event(session.name, "paged", pages=len(pages), reason=reason, control=first.group(3))
    session.trace.event(session.name, "paged_text", quiet=True, text="\n".join(out))
    return "\n".join(out)


async def read_pages(ctx: RunContext[Deps], urls: list[str]) -> str:
    """Open several pages of this website one after the other and read them all in one step.

    Pass link targets the current page shows (the part after "->"), e.g. the detail pages or tabs of several
    records you want to compare. Use it instead of opening them one by one.
    """
    session, deadline = ctx.deps.session, ctx.deps.deadline
    out, used, opened = [], 0, 0
    base = session.page.url
    for number, url in enumerate(urls[:MAX_READ], 1):
        target = urljoin(base, url)
        if urlparse(target).netloc != urlparse(session.site["url"]).netloc:
            out.append(f"\n===== {url}: not on this website, not opened")
            continue
        if used >= MAX_PAGED or (deadline is not None and time.monotonic() > deadline - 5):
            out.append(f"\n===== {url}: not opened (output limit or time); open it in a further call")
            continue
        async with session.lock:
            await session._goto(target)
            session.trace.event(session.name, "action", action="goto", url=target)
            await session.look()
        opened += 1
        text = session.view if number == min(len(urls), MAX_READ) else _plain(session.view)
        if len(text) > MAX_VIEW:
            text = text[:MAX_VIEW] + f"\n[... cut here, {len(text) - MAX_VIEW} more characters; open this page alone]"
        used += len(text)
        events = ""
        if session.events:
            events = "\nSince your last action: " + "; ".join(session.events)
            session.events.clear()
        out.append(f"\n===== {session.page.url}{events}\n{text}")
    head = (f"Opened {opened} of {len(urls)} pages. The last one is open now and only its refs work."
            + (f" At most {MAX_READ} pages are opened per call." if len(urls) > MAX_READ else ""))
    return head + "\n".join(out)


VALUE = re.compile(r"[\w/.:,+-]*\d[\w/.:,+-]*")


def unseen_values(text: str, seen: str) -> list[str]:
    """The values in `text` (anything with a digit: numbers, references, dates) that `seen` does not contain."""
    haystack = " ".join(seen.split())
    missing = []
    for token in VALUE.findall(text):
        token = token.strip(".,:;/-+")
        if token and token not in haystack and token not in missing:
            missing.append(token)
    return missing


async def note(ctx: RunContext[Deps], key: str, value: str) -> str:
    """Record a fact you can see on the current page (copy values exactly), so it survives if you run out of time."""
    missing = unseen_values(value, ctx.deps.session.seen)
    if missing:
        ctx.deps.session.trace.event(ctx.deps.session.name, "note_refused", key=key, missing=missing[:10])
        ctx.deps.refused[key] = ctx.deps.refused.get(key, 0) + 1
        if ctx.deps.refused[key] > 2:
            return (f"Not noted, again. Stop trying to note {key!r}; continue with your goal from what the current "
                    f"page shows.")
        return (f"Not noted: {', '.join(missing[:10])} appear on no page you have seen. Note only values copied "
                f"from a page; open the page again if you need to check.")
    ctx.deps.notes[key] = value
    ctx.deps.session.trace.event(ctx.deps.session.name, "note", key=key, value=value)
    return f"noted {key}"


TOOLS = [goto, click, fill, select, check, back, read_more, read_all_pages, read_pages, note]

